// The other package. Same template name, same instantiation at `i32`, and a
// body that answers its first argument — so all three of `@pick$i32`,
// `@pkg_a.pick$i32` and `@pkg_b.pick$i32` have to be separate symbols, and
// swapping any two of them changes the exit code.

const pick = <T>(a: T, b: T): T => a;

export const chooseB = (): i32 => pick(40, 1);
